import{_ as a,o as s,c as i,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-1-programmstart.png",u="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-1-programmstart-2.png",d="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-3-uebersicht.png",h="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-4-datenliste.png",c="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-5-manuelle-pruefung.png",z=JSON.parse('{"title":"Daten auf abgelaufene Aufbewahrungsfristen prüfen und löschen","description":"","frontmatter":{"title":"Daten auf abgelaufene Aufbewahrungsfristen prüfen und löschen","source_pageid":430,"source_revision":5290},"headers":[],"relativePath":"schild3/schueler/daten-gemaess-loeschfristen-loeschen-verwaltung-werkzeuge.md","filePath":"schild3/schueler/daten-gemaess-loeschfristen-loeschen-verwaltung-werkzeuge.md"}'),o={name:"schild3/schueler/daten-gemaess-loeschfristen-loeschen-verwaltung-werkzeuge.md"};function g(f,t,m,p,b,k){return s(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="daten-auf-abgelaufene-aufbewahrungsfristen-prufen-und-loschen" tabindex="-1">Daten auf abgelaufene Aufbewahrungsfristen prüfen und löschen <a class="header-anchor" href="#daten-auf-abgelaufene-aufbewahrungsfristen-prufen-und-loschen" aria-label="Permalink to &quot;Daten auf abgelaufene Aufbewahrungsfristen prüfen und löschen&quot;">​</a></h1><p>Prüfen Sie, welche gespeicherten Daten ihre Aufbewahrungsfrist überschritten haben. Die Anzeige der Prüfergebnisse und das anschließende Löschen sind getrennte Schritte.</p><p><a href="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-1-programmstart.png"><img src="'+l+'" alt="Anfrage beim Programmstart, auf Löschfristen zu prüfen." loading="lazy"></a></p><p><em>Anfrage beim Programmstart, auf Löschfristen zu prüfen.</em></p><p>SchILD-NRW unterstützt die Schulleitung dabei, datenschutzkonform zu arbeiten.</p><p>Hierzu wird eine Prüfung der Daten nach den Vorgaben der betreffenden Datenschutzverordnungen durchgeführt und es besteht die Möglichkeit, diese Daten auch direkt löschen zu lassen.</p><h2 id="prufung-auf-abgelaufene-loschfristen" tabindex="-1">Prüfung auf abgelaufene Löschfristen <a class="header-anchor" href="#prufung-auf-abgelaufene-loschfristen" aria-label="Permalink to &quot;Prüfung auf abgelaufene Löschfristen&quot;">​</a></h2><p>Per Standard wird diese Option, je nach Berechtigung des Nutzers, beim Programmstart von SchILD-NRW ausgeführt.</p><p>Administratoren bekommen an dieser Stelle auch die Möglichkeit, durch setzen des entsprechenden Hakens <em>die Prüfung beim Programmstart zu deaktivieren</em>.</p><p>Ein Klick auf <strong>Prüfen, ob Daten, deren Aufbewahrungsfristen abgelaufen sind, vorhanden sind</strong> startet die Prüfung.</p><p><a href="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-1-programmstart-2.png"><img src="'+u+'" alt="Wurden Daten gefunden, werden Sie benachrichtigt." loading="lazy"></a></p><p><em>Wurden Daten gefunden, werden Sie benachrichtigt.</em></p><p>Wurden Daten mit abgelaufenen Löschfristen gefunden, können Sie dies im folgenden Dialog über <strong>Nein</strong> zur Kenntnis nehmen und mit der geplanten Arbeit fortfahren. Alternativ lassen sich die Daten mit <strong>Ja</strong> anzeigen.</p>',13),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Bis zu diesem Schritt werden die Daten nur geprüft und angezeigt; es wurde noch nichts gelöscht.")],-1),e("p",null,[e("a",{href:"/bilder/schueler/verwaltung-werkzeuge-loeschfristen-3-uebersicht.png"},[e("img",{src:d,alt:"Übersicht über die gefundenen Daten mit abgelaufenen Löschfristen.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Übersicht über die gefundenen Daten mit abgelaufenen Löschfristen.")],-1),e("p",null,[n("Der Dialog ordnet Daten technischen Löschkategorien zu. Diese ersetzen nicht die rechtliche Zuordnung und den Fristbeginn. Für Schülerdaten unterscheidet "),e("a",{href:"https://bass.schule.nrw/101.htm",target:"_blank",rel:"noreferrer"},"§ 9 VO-DV I"),n(" insbesondere Zweitschriften von Abgangs- und Abschlusszeugnissen (50 Jahre), Schülerstammblätter (20 Jahre), die dort genannten weiteren Zeugnis- und Prüfungsunterlagen (10 Jahre) und übrige Daten (5 Jahre). Die Frist beginnt mit Ablauf des Abschlusskalenderjahres der Dateien oder Akten, jedoch nicht vor Ablauf des Kalenderjahres, in dem die Schulpflicht endet. Für Lehrkräftedaten gilt gesondert die VO-DV II.")],-1),e("p",null,'Weiterhin wird noch auf "Sonstige" Daten geprüft, die aus der Datenbank entfernt werden sollten oder müssen.',-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Prüfen Sie die vom Programm angebotenen Kategorien gegen die tatsächlich betroffenen Unterlagen. Eine technische Feldgruppe wie "),e("em",null,"Adressdaten"),n(" oder "),e("em",null,"Lernabschnittsdaten"),n(" ist für sich keine rechtliche Fristbestimmung. Klären Sie vor der endgültigen Löschung die Anbietung an das zuständige Archiv gemäß § 9 Absatz 3 VO-DV I.")]),e("p",null,[n("Unter "),e("em",null,"Sonstiges"),n(" fallen z.B. mit Löschmarkierung versehene Schüler oder welche, die mehrere Jahre in der Warteliste oder der Neuaufnahme verblieben sind.")])],-1),r("<p>Bei einer vorgesehen Löschung besteht die Möglichkeit, die jeweiligen Kategorien, also <em>&quot;Schüler&quot;&quot;</em> oder <em>&quot;Lehrer&quot;</em> bei den betreffenden Fristen über entsprechende Haken an- oder abzuwählen.</p><p>Weiterhin wird angeboten, bei den Lehrerdaten <em>Kürzel</em> und <em>Namen</em> zu behalten, so dass die Zuordnungen bei den Leistungsdaten weiterhin erhalten bleiben.</p><p>Schlussendlich bietet SchILD-NRW an, die <em>Dokumentenverwaltung</em> trotz des Ablaufs der Löschfristen zu erhalten.</p>",3),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Beachten Sie, dass es sich hierbei auch um die als .pdf archivierten Zeugnisse handelt."),e("p",null,"Beachten Sie weiterhin, dass es sich bei .pdfs um digitale Daten handelt, die ebenfalls unter eventuelle DVO-Bestimmungen fallen.")],-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Für die datenschutzkonforme Handhabung digitaler Daten und korrekte Archivierung auf Ausdrucken im jeweils zeitlich aktuellen Rechtsrahmen ist die Schulleitung verantwortlich. Die Werkzeuge von SchILD-NRW dienen lediglich der unverbindlichen Unterstützung.")],-1),r('<p><a href="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-4-datenliste.png"><img src="'+h+'" alt="Anzeigen der betroffenen Datensätze über Namen anzeigen." loading="lazy"></a></p><p><em>Anzeigen der betroffenen Datensätze über Namen anzeigen.</em></p><p>Die Schaltfläche <em>Namen anzeigen</em> zeigt eine Liste der betroffenen Personen, aufgelistet je nach Kategorie. Diese Liste kann <em>gedruckt</em>, <em>gespeichert</em> oder einfach nur durchgesehen werden.</p><h2 id="daten-loschen" tabindex="-1">Daten löschen <a class="header-anchor" href="#daten-loschen" aria-label="Permalink to &quot;Daten löschen&quot;">​</a></h2><p>Kontrollieren Sie vor der endgültigen Löschung nochmals die ausgewählten Kategorien.</p><p>Mit <strong>Zurück</strong> oder dem <strong>X</strong> des Fensters schließen Sie den Prüfdialog ohne Löschung und starten SchILD-NRW.</p><p>Haben Sie die Wahl der zu löschenden Daten getroffen, führt ein Klick auf <strong>Daten jetzt löschen</strong> diese aus.</p><p>Bestätigen Sie die Warnung <strong>Die markierten Daten werden jetzt endgültig gelöscht!</strong> nur, wenn Sie die Löschung ausführen möchten. Mit <strong>Abbrechen</strong> beenden Sie den Vorgang an dieser Stelle ohne Löschung.</p><p>Nach dem Löschvorgang startet SchILD-NRW.</p><h2 id="manuelles-prufen-auf-abgelaufene-loschfristen-anstoßen" tabindex="-1">Manuelles Prüfen auf abgelaufene Löschfristen anstoßen <a class="header-anchor" href="#manuelles-prufen-auf-abgelaufene-loschfristen-anstoßen" aria-label="Permalink to &quot;Manuelles Prüfen auf abgelaufene Löschfristen anstoßen&quot;">​</a></h2><p><a href="/bilder/schueler/verwaltung-werkzeuge-loeschfristen-5-manuelle-pruefung.png"><img src="'+c+'" alt="Manuelles Anstoßen der Löschfristenprüfung." loading="lazy"></a></p><p><em>Manuelles Anstoßen der Löschfristenprüfung.</em></p><p>Über <em>Verwaltung ➜ Werkzeuge</em> ➜ <strong>Löschfristen prüfen</strong> lässt sich die Prüfung jederzeit direkt starten.</p><p>Dies kann hilfreich sein, wenn die automatische Prüfung beim Systemstart deaktiviert wurde.</p><p>In diesem Beispiel finden sich keine zu löschenden Daten, da diese gerade durchgeführt wurde.</p><p>Mit der Option <strong>Basisdaten für die Ehemaligenverwaltung behalten</strong> steuern Sie den Erhalt der betreffenden Basisdaten. Eine Programmauswahl allein begründet jedoch keine zusätzliche Aufbewahrungsbefugnis.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Daten_gem%C3%A4%C3%9F_l%C3%B6schfristen_l%C3%B6schen_(Verwaltung_Werkzeuge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5290.</p>',18)])])}const _=a(o,[["render",g]]);export{z as __pageData,_ as default};
